// Every workflow whose nodes touch money/outbound tags must call the
// Anton Gate workflow (a node whose webhook path is 'anton-gate') before
// any node tagged risky. This is a structural check, not a content check
// -- it verifies the Gate call exists and sits upstream, not that the
// workflow's business logic is otherwise correct.
const GATE_WEBHOOK_PATH = 'anton-gate';
const RISKY_TAGS = ['money', 'outbound'];

const results = [];
for (const item of $input.all()) {
  const wf = item.json;
  // Skip the Gate and Auditor workflows themselves, and anything not
  // explicitly tagged for this audit -- see the room's deploy skill,
  // which tags every Generator-built workflow it creates.
  const tags = (wf.tags || []).map(t => (t.name || t));
  if (tags.includes('anton-gate') || tags.includes('anton-auditor')) continue;
  if (!tags.includes('anton-managed')) continue;

  const hasRiskyNode = tags.some(t => RISKY_TAGS.includes(t));
  if (!hasRiskyNode) {
    results.push({ id: wf.id, name: wf.name, compliant: true, reason: 'no money/outbound tag, gate not required' });
    continue;
  }

  const nodes = wf.nodes || [];
  const hasGateCall = nodes.some(n =>
    n.type === 'n8n-nodes-base.httpRequest' &&
    typeof n.parameters?.url === 'string' &&
    n.parameters.url.includes(GATE_WEBHOOK_PATH)
  );
  results.push({
    id: wf.id,
    name: wf.name,
    compliant: hasGateCall,
    reason: hasGateCall ? 'gate call found' : 'MISSING gate call before a money/outbound-tagged workflow',
  });
}
return results.map(r => ({ json: r }));
